import type { CreatureDef, MoveDef } from '../creature-types';

/**
 * The Triassic roster: 21 playable animals across four rungs and four shore animals that are never
 * played (docs/triassic/01-triassic-design.md). Lengths are game units under 4.0 · metres^0.55,
 * which keeps the real order and near-real proportion over 1.4–19 units; `adultLength`, `speed`,
 * `burst`, `agility`, `turnRate` and `glide` are GENERATED by tools/triassic/stats.mjs from
 * docs/research/triassic-swimming.json (representative lengths and swimming performance with
 * sources). Do not hand-edit those six fields — rerun the script. Every mechanic flag is a game
 * reading of anatomy in the design document, not a claim of fossil behaviour, and the Helicoprion
 * is on the roster as a labelled Permian relict. Model assets are pending; every animal here
 * borrows a Devonian body (src/content/triassic/index.ts) until its own lands.
 */
const light = (name: string, o: Partial<MoveDef> = {}): MoveDef => ({
  name, windup: 0.14, active: 0.16, recovery: 0.22, damage: 9, poise: 12, knockback: 1.2, stamina: 6, lunge: 0.25, ...o,
});
const heavy = (name: string, o: Partial<MoveDef> = {}): MoveDef => ({
  name, windup: 0.42, active: 0.2, recovery: 0.5, damage: 24, poise: 45, knockback: 3.5, stamina: 18, lunge: 0.9, guardBreak: true, ...o,
});
/** A mouth that cannot bite anything worth biting: the strainers, the grazer, the toothless. */
const nibble = (name: string): MoveDef => ({ name, windup: 0.2, active: 0.15, recovery: 0.3, damage: 1, poise: 2, knockback: 0.3, stamina: 4, lunge: 0.1 });

